/**
 * Volado Labs — Elementor CSS integrity guard (permanent).
 * Fixes recurring "page renders flush-left / unstyled containers" caused by:
 * blanket Elementor cache purges wiping ALL posts' CSS meta + lazy per-visit
 * regeneration occasionally persisting incomplete CSS that page caches freeze.
 */

// A) After ANY Elementor cache purge: regenerate every post's CSS immediately
//    (single consistent context, no lazy-regen window), then flush SG cache.
add_action('elementor/core/files/clear_cache', function () {
    if (!class_exists('\Elementor\Plugin')) { return; }
    ignore_user_abort(true);
    if (function_exists('set_time_limit')) { @set_time_limit(300); }
    global $wpdb;
    $ids = $wpdb->get_col("SELECT DISTINCT pm.post_id FROM {$wpdb->postmeta} pm JOIN {$wpdb->posts} p ON p.ID = pm.post_id WHERE pm.meta_key = '_elementor_data' AND pm.meta_value LIKE '[%' AND p.post_status IN ('publish','private','draft')");
    $n = 0;
    foreach ($ids as $id) {
        try { \Elementor\Core\Files\CSS\Post::create((int) $id)->update(); $n++; } catch (\Throwable $e) {}
    }
    update_option('volado_css_regen_log', $n . ' of ' . count($ids) . ' regenerated @' . gmdate('c'), false);
    try { do_action('siteground_optimizer_flush_cache'); } catch (\Throwable $e) {}
}, 999);

// B) Self-heal on the front end: a page whose data contains containers but whose
//    stored CSS has zero --display rules is poisoned -> rebuild before serving.
add_action('wp', function () {
    if (is_admin() || !is_singular()) { return; }
    $id = get_the_ID();
    if (!$id || !class_exists('\Elementor\Plugin')) { return; }
    $data = get_post_meta($id, '_elementor_data', true);
    if (!is_string($data) || strpos($data, '"elType":"container"') === false) { return; }
    $meta = get_post_meta($id, '_elementor_css', true);
    if (!is_array($meta) || empty($meta['status']) || !isset($meta['css']) || !is_string($meta['css'])) { return; }
    if (strpos($meta['css'], '--display') !== false) { return; } // healthy
    try {
        \Elementor\Core\Files\CSS\Post::create($id)->update();
        update_option('volado_css_selfheal_log', $id . ' healed @' . gmdate('c'), false);
    } catch (\Throwable $e) {}
}, 5);

// C) REST/programmatic edits: when _elementor_data is written, regenerate that
//    page's CSS at once and purge its URL from SG cache (no global purge needed).
$volado_regen_on_meta = function ($meta_id, $post_id, $meta_key) {
    if ('_elementor_data' !== $meta_key || !class_exists('\Elementor\Plugin')) { return; }
    try {
        \Elementor\Core\Files\CSS\Post::create((int) $post_id)->update();
        $url = get_permalink($post_id);
        if ($url && class_exists('\SiteGround_Optimizer\Supercacher\Supercacher') && method_exists('\SiteGround_Optimizer\Supercacher\Supercacher', 'purge_cache_request')) {
            \SiteGround_Optimizer\Supercacher\Supercacher::purge_cache_request($url);
        }
    } catch (\Throwable $e) {}
};
add_action('updated_post_meta', $volado_regen_on_meta, 10, 3);
add_action('added_post_meta', $volado_regen_on_meta, 10, 3);
